async function checkLoanAppLimit(c, next) {
  const user = c.get("user");
  if (!user) {
    throw new HTTPException(401, { message: "Authentication required" });
  }
  const [userRecord] = await db2.select({
    plan: users.plan,
    subscriptionStatus: users.subscriptionStatus
  }).from(users).where(eq(users.id, user.id)).limit(1);
  if (!userRecord) {
    throw new HTTPException(404, { message: "User not found" });
  }
  if (userRecord.subscriptionStatus !== "active") {
    throw new HTTPException(403, {
      message: "Active subscription required to create loan apps."
    });
  }
  const maxApps = getMaxLoanApps(userRecord.plan);
  if (maxApps === Infinity) {
    await next();
    return;
  }
  const { loanApps: loanApps2 } = await Promise.resolve().then(() => (init_schema2(), exports_schema));
  const userLoanApps = await db2.select().from(loanApps2).where(eq(loanApps2.ownerId, user.id));
  if (userLoanApps.length >= maxApps) {
    throw new HTTPException(403, {
      message: `You have reached the maximum number of loan apps (${maxApps}) for your ${userRecord.plan} plan. Please upgrade to create more.`
    });
  }
  await next();
}
