init_db2();
init_schema2();
init_drizzle_orm();
var usersRepo = {
  async findByEmail(email) {
    return db2.query.users.findFirst({
      where: eq(users.email, email)
    });
  },
  async findById(id) {
    return db2.query.users.findFirst({
      where: eq(users.id, id)
    });
  },
  async saveSession(data) {
    await db2.transaction(async (tx) => {
      await tx.update(userSessions).set({ isCurrent: false }).where(eq(userSessions.userId, data.userId));
      const existing = await tx.select().from(userSessions).where(and(eq(userSessions.userId, data.userId), eq(userSessions.deviceFingerprint, data.deviceFingerprint))).limit(1);
      if (existing.length) {
        await tx.update(userSessions).set({
          isCurrent: true,
          lastActiveAt: new Date,
          ipAddress: data.ipAddress
        }).where(eq(userSessions.id, existing[0].id));
      } else {
        await tx.insert(userSessions).values({
          userId: data.userId,
          deviceFingerprint: data.deviceFingerprint,
          deviceName: data.deviceName,
          browser: data.browser,
          os: data.os,
          ipAddress: data.ipAddress,
          city: data.city,
          country: data.country,
          isCurrent: true
        });
      }
    });
  },
  async create(data) {
    const [user] = await db2.insert(users).values({
      email: data.email,
      passwordHash: data.passwordHash,
      fullName: data.fullName,
      phone: data.phone
    }).returning();
    return user;
  },
  async updateResetToken(email, token, expires) {
    const [updated] = await db2.update(users).set({ resetPasswordToken: token, resetPasswordExpires: expires }).where(eq(users.email, email)).returning();
    return updated;
  },
  async findByResetToken(token) {
    return db2.query.users.findFirst({
      where: eq(users.resetPasswordToken, token)
    });
  },
  async updatePassword(id, passwordHash) {
    const [updated] = await db2.update(users).set({
      passwordHash,
      resetPasswordToken: null,
      resetPasswordExpires: null
    }).where(eq(users.id, id)).returning();
    return updated;
  }
};
// src/domain/auth/service.ts
init_auth();
var authService = {
  async register(input) {
    if (!input.email || !input.password) {
      return {
        success: false,
        error: { code: 400, message: "Email and password are required" }
      };
    }
    const existingUser = await usersRepo.findByEmail(input.email);
    if (existingUser) {
      return {
        success: false,
        error: { code: 400, message: "User already exists" }
      };
    }
    const passwordHash = await hashPassword(input.password);
    const user = await usersRepo.create({
      email: input.email,
      passwordHash,
      fullName: input.fullName,
      phone: input.phone
    });
    const token = await signToken({
      id: user.id,
      email: user.email,
      role: user.role
    });
    const { passwordHash: _, ...userWithoutPassword } = user;
    return { success: true, data: { user: userWithoutPassword, token } };
  },
  async login(input) {
    if (!input.email || !input.password) {
      return {
        success: false,
        error: { code: 400, message: "Email and password are required" }
      };
    }
    const user = await usersRepo.findByEmail(input.email);
    if (!user) {
      return {
        success: false,
        error: { code: 401, message: "Invalid credentials" }
      };
    }
    const isValid = await comparePassword(input.password, user.passwordHash);
    if (!isValid) {
      return {
        success: false,
        error: { code: 401, message: "Invalid credentials" }
      };
    }
    const token = await signToken({
      id: user.id,
      email: user.email,
      role: user.role
    });
    const { passwordHash: _, ...userWithoutPassword } = user;
    return { success: true, data: { user: userWithoutPassword, token } };
  },
  async saveSessions(data) {
    await usersRepo.saveSession(data);
  },
  async getMe(userId) {
    const user = await usersRepo.findById(userId);
    if (!user) {
      return { success: true, data: { user: null } };
    }
    const { passwordHash: _, ...userWithoutPassword } = user;
    return { success: true, data: { user: userWithoutPassword } };
  },
  async changePassword(userId, oldPassword, newPassword) {
    const user = await usersRepo.findById(userId);
    if (!user) {
      return {
        success: false,
        error: { code: 404, message: "User not found" }
      };
    }
    const isValid = await comparePassword(oldPassword, user.passwordHash);
    if (!isValid) {
      return {
        success: false,
        error: { code: 401, message: "Current password is incorrect" }
      };
    }
    const passwordHash = await hashPassword(newPassword);
    await usersRepo.updatePassword(userId, passwordHash);
    return { success: true, data: { success: true } };
  }
};
