router5.post("/login", async (c) => {
  try {
    const { identifier, passcode } = await c.req.json();
    if (!identifier || !passcode) {
      return c.json({ status: "error", message: "Identifier and passcode are required" }, 400);
    }
    const { eq: eq2, or: or2 } = await Promise.resolve().then(() => (init_drizzle_orm(), exports_drizzle_orm));
    const { db: db3, borrowers: borrowers2 } = await Promise.resolve().then(() => (init_db2(), exports_db));
    const { comparePassword: comparePassword2 } = await Promise.resolve().then(() => (init_auth(), exports_auth));
    const borrower = await db3.query.borrowers.findFirst({
      where: or2(eq2(borrowers2.email, identifier), eq2(borrowers2.phone, identifier))
    });
    if (!borrower || !borrower.passcodeHash) {
      return c.json({ status: "error", message: "Invalid credentials" }, 401);
    }
    const isValid = await comparePassword2(passcode, borrower.passcodeHash);
    if (!isValid) {
      return c.json({ status: "error", message: "Invalid credentials" }, 401);
    }
    const token = await signBorrowerToken(borrower);
    return c.json({
      status: "success",
      message: "Login successful",
      token,
      borrower: {
        id: borrower.id,
        firstName: borrower.firstName,
        lastName: borrower.lastName,
        email: borrower.email,
        phone: borrower.phone
      }
    });
  } catch (error48) {
    return c.json({ status: "error", message: error48.message }, 400);
  }
});
