var router6 = new Hono2;
router6.post("/paystack", async (c) => {
  console.log("--- \uD83D\uDCE5 Paystack Webhook Received ---");
  try {
    const signature = c.req.header("x-paystack-signature");
    const rawBody = await c.req.text();
    if (!signature) {
      console.error("\u274C Paystack webhook: No signature provided");
      return c.json({ error: "No signature provided" }, 400);
    }
    const { paystackService: paystackService2 } = await Promise.resolve().then(() => (init_paystack(), exports_paystack));
    const isValid = paystackService2.verifyWebhookSignature(rawBody, signature);
    if (!isValid) {
      console.error("\u274C Paystack webhook: Invalid signature");
      return c.json({ error: "Invalid signature" }, 400);
    }
    console.log("\u2705 Paystack signature verified");
    const body = JSON.parse(rawBody);
    const event = body.event;
    console.log(`\uD83D\uDD14 Paystack Event: ${event}`);
    if (event === "charge.success") {
      const { reference, status, paid_at, metadata, authorization } = body.data;
      console.log("\uD83D\uDCB0 Processing charge.success:", {
        reference,
        status,
        metadata
      });
      if (metadata?.type === "BORROWER_ADD_CARD" || metadata?.type === "CARD_INITIALIZATION") {
        console.log("\uD83D\uDCB3 Handling Add Card flow:", reference);
        const borrowerEmail = metadata.borrowerEmail;
        if (!borrowerEmail) {
          console.error("\u26A0\uFE0F No borrowerEmail found in metadata for Add Card flow");
          return c.json({ error: "No borrowerEmail found in metadata" }, 400);
        }
        console.log(`\uD83D\uDD0D Looking up borrower by email: ${borrowerEmail}`);
        const { paymentMethods: paymentMethods2, borrowers: borrowers2 } = await Promise.resolve().then(() => (init_schema2(), exports_schema));
        const borrower = await db2.select().from(borrowers2).where(eq(borrowers2.email, borrowerEmail)).limit(1);
        if (!borrower || borrower.length === 0) {
          console.error(`\u274C Borrower not found for email: ${borrowerEmail}`);
          return c.json({ error: "Borrower not found" }, 404);
        }
        console.log(`\u2705 Borrower found: ${borrower[0].id}. Saving authorization...`);
        await db2.insert(paymentMethods2).values({
          borrowerId: borrower[0].id,
          authorizationCode: authorization.authorization_code,
          last4: authorization.last4,
          expiry: `${authorization.exp_month}/${authorization.exp_year}`,
          provider: "PAYSTACK"
        });
        console.log(`\u2728 Card authorization successfully saved for borrower: ${borrower[0].id}`);
        return c.json({
          status: "acknowledged",
          message: "Card authorization saved"
        });
      }
      if (metadata?.type === "LENDER_FUNDING") {
        console.log("\uD83D\uDCB0 Processing Lender Funding:", reference);
        const { lenderWalletService: lenderWalletService2 } = await Promise.resolve().then(() => (init_service2(), exports_service));
        const result = await lenderWalletService2.processSuccessfulFunding(reference, body.data);
        console.log(`\u2728 Wallet successfully credited for lender: ${metadata.lenderId}`);
        return c.json({
          status: "acknowledged",
          message: "Lender wallet credited",
          data: result
        });
      }
      if (metadata?.type === "REPAYMENT") {
        console.log("\uD83D\uDCB0 Incoming REPAYMENT payment");
        const { loan_id } = metadata;
        let amountToDistribute = Number(body.data.amount) / 100;
        console.log("\uD83D\uDCB5 Total amount received:", amountToDistribute);
        const allRepaymentsNotPaid = await db2.query.repayments.findMany({
          where: and(eq(repayments.loanId, loan_id), or(eq(repayments.status, "PARTIAL"), eq(repayments.status, "PENDING"))),
          orderBy: (repayments2, { asc: asc2 }) => [asc2(repayments2.dueDate)]
        });
        if (allRepaymentsNotPaid.length === 0) {
          console.log("\u274C No unpaid repayments found");
          return c.json({ error: "No repayment found" }, 404);
        }
        console.log(`\uD83D\uDCC4 Found ${allRepaymentsNotPaid.length} unpaid repayments`);
        for (const repayment of allRepaymentsNotPaid) {
          if (amountToDistribute <= 0) {
            console.log("\u2705 Payment fully distributed");
            break;
          }
          console.log(`\u27A1\uFE0F Processing repayment ${repayment.id}`);
          const unitPayments = await db2.query.subRepayments.findMany({
            where: eq(subRepayments.repaymentId, repayment.id)
          });
          const totalPaid = unitPayments.filter((p) => p.status === "PAID").reduce((acc, pay) => acc + Number(pay.amount), 0);
          const repaymentAmount = Number(repayment.amount);
          const remainingAmount = repaymentAmount - totalPaid;
          console.log({
            repaymentId: repayment.id,
            repaymentAmount,
            totalPaid,
            remainingAmount
          });
          if (remainingAmount <= 0) {
            console.log("\u26A0\uFE0F Repayment already fully settled, skipping");
            continue;
          }
          const amountApplied = Math.min(remainingAmount, amountToDistribute);
          console.log(`\uD83D\uDCB3 Applying ${amountApplied} to repayment ${repayment.id}`);
          await db2.insert(subRepayments).values({
            repaymentId: repayment.id,
            amount: String(amountApplied),
            status: "PAID",
            paidAt: new Date
          });
          amountToDistribute -= amountApplied;
          console.log(`\uD83D\uDCC9 Remaining amount to distribute: ${amountToDistribute}`);
          if (amountApplied === remainingAmount) {
            console.log(`\u2705 Repayment ${repayment.id} fully PAID`);
            await db2.update(repayments).set({
              status: "PAID",
              paidAt: new Date
            }).where(eq(repayments.id, repayment.id));
          } else {
            console.log(`\uD83D\uDFE1 Repayment ${repayment.id} PARTIALLY PAID`);
            await db2.update(repayments).set({
              status: "PARTIAL"
            }).where(eq(repayments.id, repayment.id));
          }
        }
        if (amountToDistribute > 0) {
          console.log("\u26A0\uFE0F Payment exceeds total outstanding repayments", amountToDistribute);
        }
        console.log("\uD83C\uDF89 Repayment distribution completed successfully");
        return c.json({
          status: "acknowledged",
          message: "Repayment processed successfully"
        });
      }
    }
    console.log(`\u2753 Unhandled Paystack event: ${event}`);
    return c.json({ status: "acknowledged" }, 200);
  } catch (error48) {
    console.error("\uD83D\uDCA5 Paystack webhook error:", error48);
    return c.json({
      error: error48 instanceof Error ? error48.message : "Failed to process webhook"
    }, 500);
  } finally {
    console.log("--- \uD83D\uDD1A Paystack Webhook Processed ---");
  }
});
