// src/utils/upload.ts
var uploadToCloudinary = async (file2, folder = "hubsell_uploads") => {
  const buffer2 = Buffer.from(await file2.arrayBuffer());
  return new Promise((resolve, reject) => {
    import_cloudinary2.v2.uploader.upload_stream({
      folder,
      resource_type: "auto",
      unique_filename: true,
      overwrite: false
    }, (error48, result) => {
      if (error48)
        return reject(error48);
      if (!result?.secure_url) {
        return reject(new Error("Cloudinary upload failed"));
      }
      resolve(result.secure_url);
    }).end(buffer2);
  });
};

