router13.post("/auth/login", async (c) => {
  try {
    const { identifier, passcode } = await c.req.json();
    if (!identifier || !passcode) {
      return c.json({ status: "error", message: "Identifier and passcode are required" }, 400);
    }
    const borrower = await db2.query.borrowers.findFirst({
      where: (borrowers3, { or: or2, eq: eq2 }) => or2(eq2(borrowers3.email, identifier), eq2(borrowers3.phone, identifier))
    });
    if (!borrower || !borrower.passcodeHash) {
      return c.json({ status: "error", message: "Invalid credentials" }, 401);
    }
    const isValid = await comparePassword(passcode, borrower.passcodeHash);
    if (!isValid) {
      return c.json({ status: "error", message: "Invalid credentials" }, 401);
    }
    const token = await signToken({
      id: borrower.id,
      borrowerId: borrower.id,
      email: borrower.email,
      phone: borrower.phone,
      role: "BORROWER"
    });
    return c.json({
      status: "success",
      message: "Login successful",
      token,
      borrower: {
        id: borrower.id,
        firstName: borrower.firstName,
        lastName: borrower.lastName,
        email: borrower.email,
        phone: borrower.phone
      }
    });
  } catch (error48) {
    return c.json({ status: "error", message: error48.message }, 400);
  }
});
